const ACCOUNT_URL='https://hdmcpvibooweybzrwgrf.supabase.co';
const ACCOUNT_KEY='sb_publishable__QVS5nUmhvNg1dXzioFRnQ_F4VGZang';
const REDIRECT_URL=location.origin+'/';
const clone=x=>JSON.parse(JSON.stringify(x));
const accountDefaults=clone({commander,managers,agents,projects:[],logs:[],histories:{}});
let accountClient,accountUser=null,accountReady=false,accountEpoch=0,accountRevision=0;
let accountHistories={},accountTimer,accountFlight=null,accountLast='',accountDirty=false,accountConflict=false,accountLoading=false,authMode='login';
const gate=document.getElementById('account-gate');
const appShell=document.querySelector('.shell');
function accountSnapshot(){return clone({schemaVersion:1,commander,managers,agents,projects,logs:logs.slice(0,100),histories:accountHistories})}
function accountApply(x){if(!x||!Array.isArray(x.projects)||!Array.isArray(x.agents))throw Error('数据格式不正确');commander=clone(x.commander||accountDefaults.commander);managers=clone(x.managers||accountDefaults.managers);agents=clone(x.agents);projects=clone(x.projects);logs=clone(x.logs||[]);accountHistories=clone(x.histories||{});chats={}}
function accountCacheKey(){return 'linghang-account-cache-v1:'+accountUser.id}
function accountCache(){localStorage.setItem(accountCacheKey(),JSON.stringify({revision:accountRevision,dirty:accountDirty,base:accountLast?JSON.parse(accountLast):null,payload:accountSnapshot()}))}
function syncLabel(text,error=false){const el=document.getElementById('cloud-status');if(el){el.textContent=text;el.classList.toggle('sync-error',error)}}
function accountStage(){if(!accountReady||!accountUser)return;const json=JSON.stringify(accountSnapshot());if(accountRevision>0&&sameWorkspace(accountSnapshot(),accountLast?JSON.parse(accountLast):null)&&!accountDirty)return;accountDirty=true;try{accountCache()}catch(e){syncLabel('本机缓存失败，正在尝试云端保存',true)}syncLabel(accountConflict?'同步冲突，请处理':'待同步',accountConflict);clearTimeout(accountTimer);accountTimer=setTimeout(()=>accountFlush(),700)}
function canonicalWorkspace(value){if(!value)return null;const x=clone(value);for(const a of x.agents||[]){delete a.status;delete a.active;delete a.hasError}for(const m of x.managers||[])delete m.status;for(const p of x.projects||[]){delete p.status;for(const t of p.tasks||[])delete t.runToken}const sort=v=>Array.isArray(v)?v.map(sort):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,sort(v[k])])):v;return JSON.stringify(sort(x))}
function sameWorkspace(a,b){return !!a&&!!b&&canonicalWorkspace(a)===canonicalWorkspace(b)}
async function reconcileAccount(epoch){const user=accountUser;const {data,error}=await accountClient.from('linghang_workspaces').select('payload,revision').eq('user_id',user.id).maybeSingle();if(epoch!==accountEpoch)return false;if(error)throw error;if(!data){accountConflict=true;return false}const local=accountSnapshot(),base=accountLast?JSON.parse(accountLast):null,remote=data.payload;
 if(sameWorkspace(local,remote)){accountRevision=Number(data.revision);accountLast=JSON.stringify(remote);accountDirty=false;accountConflict=false}
 else if(base&&sameWorkspace(base,remote)){accountRevision=Number(data.revision);accountLast=JSON.stringify(remote);accountDirty=true;accountConflict=false}
 else if(base&&sameWorkspace(local,base)){stopAccountJobs();accountApply(remote);accountRevision=Number(data.revision);accountLast=JSON.stringify(remote);accountDirty=false;accountConflict=false;accountReady=false;refresh();accountReady=true}
 else{accountConflict=true;return false}try{accountCache()}catch(e){}return true}
async function accountFlush(){if(!accountReady||!accountUser)return false;if(accountFlight)return accountFlight;if(!accountDirty&&!accountConflict){syncLabel('已同步云端');return true}clearTimeout(accountTimer);const epoch=accountEpoch;
 accountFlight=(async()=>{let reconciliations=0;try{if(accountConflict){if(!(await reconcileAccount(epoch)))throw Error('WORKSPACE_CONFLICT');reconciliations++}while(accountDirty&&epoch===accountEpoch){const payload=accountSnapshot();syncLabel('正在同步…');const {data,error}=await accountClient.rpc('linghang_save_workspace',{expected_revision:accountRevision,new_payload:payload});if(epoch!==accountEpoch)return false;if(error){if(String(error.message).includes('WORKSPACE_CONFLICT')&&reconciliations++<2&&await reconcileAccount(epoch))continue;throw error}accountRevision=Number(data);accountLast=JSON.stringify(payload);accountDirty=!sameWorkspace(accountSnapshot(),payload);try{accountCache()}catch(e){/* Cloud has accepted this revision. */}}if(epoch!==accountEpoch)return false;syncLabel('已同步云端');return true}catch(e){if(epoch!==accountEpoch)return false;accountConflict=accountConflict||String(e.message).includes('WORKSPACE_CONFLICT');syncLabel(accountConflict?'存在不同修改 · 点击处理':'同步失败 · 点击重试',true);return false}finally{if(epoch===accountEpoch)accountFlight=null}})();return accountFlight}

function stopAccountJobs(){for(const p of projects)for(const t of p.tasks)t.runToken=(t.runToken||0)+1}
function hideWorkspace(){stopAccountJobs();accountEpoch++;accountReady=false;accountLoading=false;accountUser=null;accountFlight=null;clearTimeout(accountTimer);accountHistories={};projects=[];agents=[];logs=[];chats={};appShell.hidden=true;document.getElementById('overlay').classList.remove('open');document.getElementById('content').innerHTML='';document.getElementById('team-list').innerHTML='';gate.hidden=false}
function authError(error){const message=String(error?.message||'');if(/Invalid login credentials/i.test(message))return '邮箱或密码不正确。';if(/Email not confirmed/i.test(message))return '请先打开确认邮件，验证邮箱后再登录。';if(/rate limit|too many|security purposes/i.test(message))return '操作过于频繁，请稍后重试。';if(/signups not allowed|signup.*disabled/i.test(message))return '当前未开放注册，请联系管理员。';if(/fetch|network/i.test(message))return '连接失败，请检查网络后重试。';if(/password/i.test(message))return '密码未满足要求，请使用至少 12 位的强密码。';if(/email address.*invalid/i.test(message))return '请检查邮箱地址。';if(/email.*sending|smtp/i.test(message))return '邮件发送失败，请管理员检查 Supabase 发信配置。';return '操作未完成，请稍后重试，或联系管理员检查账号服务配置。'}
function authScreen(mode='login',message=''){authMode=mode;gate.hidden=false;appShell.hidden=true;const titles={login:'登录你的工作空间',signup:'创建你的账号',reset:'找回密码',password:'设置新密码'};gate.innerHTML=`<section class="account-card"><div class="account-brand"><span class="logo">⌘</span><b>领航</b></div><h1>${titles[mode]}</h1><p>项目、团队与工作记录，随账号保存。</p><form id="auth-form" onsubmit="event.preventDefault();accountSubmit(this)">${mode!=='password'?'<label class="field">邮箱<input name="email" type="email" autocomplete="email" required placeholder="you@example.com"></label>':''}${mode!=='reset'?`<label class="field">密码<input name="password" type="password" autocomplete="${mode==='login'?'current-password':'new-password'}" ${mode==='login'?'':'minlength="12"'} required placeholder="${mode==='login'?'输入密码':'至少 12 位'}"></label>`:''}${['signup','password'].includes(mode)?'<label class="field">确认密码<input name="confirm" type="password" autocomplete="new-password" minlength="12" required placeholder="再次输入密码"></label>':''}<p id="auth-message" class="auth-message" role="status">${esc(message)}</p><button class="primary auth-submit">${({login:'登录',signup:'注册',reset:'发送重置邮件',password:'保存新密码'})[mode]}</button></form><div class="auth-links">${mode==='login'?'<button onclick="authScreen(\'signup\')">注册账号</button><button onclick="authScreen(\'reset\')">忘记密码？</button>':'<button onclick="authScreen(\'login\')">返回登录</button>'}</div><p class="auth-foot">使用邮箱和密码登录。AI 员工执行仍为模拟演示。</p></section>`}
async function accountSubmit(form){const d=new FormData(form),mode=authMode,email=String(d.get('email')||'').trim(),password=d.get('password');const output=document.getElementById('auth-message'),button=form.querySelector('button');if(['signup','password'].includes(mode)&&password!==d.get('confirm')){output.textContent='两次密码不一致。';return}button.disabled=true;output.textContent='正在处理…';try{if(!accountClient)throw Error('network');let r;if(mode==='login'){r=await accountClient.auth.signInWithPassword({email,password});if(r.error)throw r.error;form.reset();await loadAccount(r.data.user)}else if(mode==='signup'){r=await accountClient.auth.signUp({email,password,options:{emailRedirectTo:REDIRECT_URL}});if(r.error)throw r.error;form.reset();if(r.data.session)await loadAccount(r.data.user);else showVerificationNotice()}else if(mode==='reset'){r=await accountClient.auth.resetPasswordForEmail(email,{redirectTo:REDIRECT_URL});if(r.error)throw r.error;form.reset();output.textContent='若该邮箱已注册，将收到密码重置邮件，请检查收件箱和垃圾邮件。'}else{r=await accountClient.auth.updateUser({password});if(r.error)throw r.error;form.reset();await accountClient.auth.signOut({scope:'local'});hideWorkspace();authScreen('login','密码已更新，请使用新密码登录。')}}catch(e){output.textContent=authError(e)}finally{button.disabled=false}}
function accountBlocked(message){appShell.hidden=true;gate.hidden=false;gate.innerHTML=`<section class="account-card"><h1>工作空间暂未就绪</h1><p>${esc(message)}</p><div class="auth-links"><button class="primary" onclick="loadAccount(accountUser,true)">重新连接</button><button class="secondary" onclick="accountLogout()">退出登录</button></div></section>`}
async function loadAccount(user,force=false){if(!user)return;if(accountLoading||(!force&&accountUser?.id===user.id&&accountReady))return;hideWorkspace();accountUser=user;accountLoading=true;const epoch=accountEpoch;gate.innerHTML='<section class="account-card"><h1>正在连接个人工作空间…</h1></section>';try{const {data,error}=await accountClient.from('linghang_workspaces').select('payload,revision').eq('user_id',user.id).maybeSingle();if(epoch!==accountEpoch)return;if(error)throw error;accountApply(data?.payload||accountDefaults);accountRevision=Number(data?.revision||0);accountLast=JSON.stringify(accountSnapshot());accountDirty=false;accountConflict=false;
 let cached=null;try{cached=JSON.parse(localStorage.getItem(accountCacheKey())||'null')}catch(e){}
 if(cached?.dirty){const remote=accountSnapshot();if(sameWorkspace(cached.payload,remote)||(cached.base&&sameWorkspace(cached.payload,cached.base))){/* The draft is already saved or has no product changes. */}else{accountApply(cached.payload);accountDirty=true;accountConflict=cached.revision!==accountRevision&&!(cached.base&&sameWorkspace(cached.base,remote));if(accountConflict){accountRevision=cached.revision;accountLast=cached.base?JSON.stringify(cached.base):''}}}
 // Simulated jobs never continue in the background while the account is closed.
 for(const p of projects)for(const t of p.tasks)if(t.status==='doing'){t.status='todo';t.phase='paused';p.paused=true;t.runToken=(t.runToken||0)+1}
 accountReady=true;gate.hidden=true;appShell.hidden=false;renderAccountBar();home();syncLabel(accountConflict?'存在不同修改 · 点击处理':accountDirty?'待同步':'已同步云端',accountConflict);if(accountDirty&&!accountConflict)await accountFlush();
 }catch(e){if(epoch===accountEpoch)accountBlocked(/PGRST205|42P01/.test(e.code||'')?'数据库尚未初始化，请管理员执行提供的账号存储脚本后重试。':'暂时无法读取云端数据，请检查网络或数据库访问规则；没有使用空数据覆盖原记录。')}finally{if(epoch===accountEpoch)accountLoading=false}}
function renderAccountBar(){document.querySelector('.user').innerHTML=`<div class="avatar">${esc((accountUser.email||'我').slice(0,1).toUpperCase())}</div><div class="account-user"><button title="账号与同步" onclick="accountPanel()">${esc(accountUser.email||'我的账号')}</button><button id="cloud-status" onclick="accountPanel()">正在连接…</button></div>`}
function accountPanel(){modal('账号与云端存储',esc(accountUser?.email||''),`<div class="notice">项目、README、员工配置、动态和版本备份按账号保存。模型 API 密钥仍为占位，不会写入此存储。</div><p class="account-sync-text">${accountConflict?'本机与云端有不同修改。可先重新检查同步；如仍需选择，请下载本机副本后再读取云端版本。未同步内容不会自动覆盖云端。':accountDirty?'有修改等待同步，请保持页面打开直到同步完成。':'当前修改已同步。'}</p><div class="account-actions"><button class="secondary" onclick="downloadAccountCopy()">下载本机副本</button>${accountConflict?'<button class="secondary" onclick="retryAccountSync()">重新检查同步</button><button class="secondary" onclick="reloadCloudPrompt()">读取云端版本</button>':'<button class="secondary" onclick="retryAccountSync()">立即同步</button>'}<button class="secondary" onclick="importLegacyPrompt()">导入旧版浏览器数据</button><button class="secondary" onclick="accountLogout()">退出登录</button></div>`)}
async function retryAccountSync(){const ok=await accountFlush();toast(ok?'已同步云端':'尚未同步，请检查网络或处理冲突');accountPanel()}
function downloadAccountCopy(){const url=URL.createObjectURL(new Blob([JSON.stringify(accountSnapshot(),null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='领航工作空间副本.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function reloadCloudPrompt(){modal('读取云端版本','本机未同步的修改将被云端版本替换，请先下载副本。',`<div class="modal-footer"><button class="secondary" onclick="downloadAccountCopy()">下载副本</button><button class="primary" onclick="reloadCloudAccount()">确认读取云端</button></div>`)}
async function reloadCloudAccount(){localStorage.removeItem(accountCacheKey());const user=accountUser;closeModal();await loadAccount(user,true)}
function importLegacyPrompt(){if(projects.length||Object.keys(accountHistories).length)return toast('仅支持向空工作空间导入，避免覆盖已有项目与备份');let x;try{x=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')}catch(e){}if(!x?.projects)return toast('当前浏览器没有旧版项目数据');modal('导入旧版数据',`将本浏览器中的 ${x.projects.length} 个项目及其版本备份复制到当前账号。请确认这些数据属于你。原数据保留。`,`<div class="modal-footer"><button class="secondary" onclick="closeModal()">取消</button><button class="primary" onclick="importLegacyAccount()">确认导入我的账号</button></div>`)}
async function importLegacyAccount(){if(projects.length||Object.keys(accountHistories).length)return;try{const x=JSON.parse(localStorage.getItem(STORAGE_KEY));x.histories={};for(const p of x.projects)x.histories[p.id]=JSON.parse(localStorage.getItem(backupKey(p.id))||'[]');accountApply(x);for(const p of projects){p.paused=true;for(const t of p.tasks)if(t.status==='doing'){t.status='todo';t.phase='paused'}}closeModal();home();accountStage();const ok=await accountFlush();toast(ok?'旧版数据已导入并同步云端':'数据已导入，云端同步尚未成功，请重试')}catch(e){toast('旧版数据读取失败，原数据未改动')}}
async function accountLogout(){if(accountDirty&&!(await accountFlush()))return toast('尚有未同步修改，请先同步或下载副本后读取云端版本');const id=accountUser?.id;const {error}=await accountClient.auth.signOut({scope:'local'});if(error)return toast('退出失败，请重试');if(id)localStorage.removeItem('linghang-account-cache-v1:'+id);hideWorkspace();authScreen()}
window.addEventListener('beforeunload',e=>{if(accountDirty){e.preventDefault();e.returnValue=''}});
window.addEventListener('online',()=>{if(accountReady&&!accountConflict)accountFlush()});
async function bootAccount(){authScreen();try{accountClient=window.supabase.createClient(ACCOUNT_URL,ACCOUNT_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});accountClient.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){setTimeout(()=>{hideWorkspace();authScreen('password')},0);return}if(event==='SIGNED_OUT'){setTimeout(()=>{hideWorkspace();authScreen()},0)}else if(event==='SIGNED_IN'&&session?.user){setTimeout(()=>{if(authMode!=='password')loadAccount(session.user)},0)}});const {data,error}=await accountClient.auth.getSession();if(error)throw error;if(data.session&&authMode!=='password')await loadAccount(data.session.user)}catch(e){authScreen('login','账号服务连接失败，请刷新页面重试。')}}
bootAccount();

function showVerificationNotice(){appShell.hidden=true;gate.hidden=false;gate.innerHTML='<section class="account-card verification-notice"><p role="status" tabindex="-1" id="verification-message">验证邮件已发送，请点击邮件中的验证链接</p></section>';document.getElementById('verification-message').focus()}
